contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // This contract is the owner of c (deployed c). Test withdrawing amounts.
    function run(uint withdrawAmount) public payable {
        // Ensure this test contract has enough Ether to later receive transfers if needed (not strictly required)
        // Observe before state via public getters
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // Attempt withdraw as owner. Must be a top-level call. Capture revert via try/catch.
        bool reverted;
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after state
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // Invariant: depositsCount never changes due to withdraw, and either withdraw succeeded and balance decreased by amount
        // or it reverted and nothing changed.
        assert(afterCount == beforeCount && ((reverted && afterBal == beforeBal) || (!reverted && beforeBal >= withdrawAmount && afterBal + withdrawAmount == beforeBal)));
    }

    // allow this contract to receive Ether so withdraw transfers can be accepted
    receive() external payable {}
}

